import { prng } from "./util";

/* ------------------------------------------------------------------ */
/*  Analytics. Buffer analytics surfaces where available; until then    */
/*  snapshots are generated by a deterministic simulator seeded by the  */
/*  publication id — clearly labelled source="simulated". No factual    */
/*  content changes are ever driven by engagement data.                 */
/* ------------------------------------------------------------------ */

export interface SnapshotDelta {
  date: string; // YYYY-MM-DD (IST)
  views: number;
  watchSeconds: number;
  avgViewSeconds: number;
  retentionPct: number;
  likes: number;
  comments: number;
  shares: number;
  followsDelta: number;
}

export function istDatesBetween(fromIst: string, toIst: string): string[] {
  const out: string[] = [];
  const d = new Date(`${fromIst}T00:00:00Z`);
  const end = new Date(`${toIst}T00:00:00Z`);
  while (d <= end) {
    out.push(d.toISOString().slice(0, 10));
    d.setUTCDate(d.getUTCDate() + 1);
  }
  return out;
}

/** Deterministic per-day performance model for demonstration. */
export function simulateDay(seedKey: string, dateIst: string, dayIndex: number): SnapshotDelta {
  const rand = prng(`${seedKey}:${dateIst}`);
  const isIg = seedKey.includes("instagram");
  const weekday = new Date(`${dateIst}T00:00:00Z`).getUTCDay();
  const weekendBoost = weekday === 0 || weekday === 6 ? 1.22 : 1;
  // Launch spike decaying to a loyal baseline; IG Reels out-reach YT Shorts here.
  const base = (isIg ? 2400 : 1450) * Math.pow(0.72, dayIndex) + (isIg ? 420 : 260);
  const views = Math.max(18, Math.round(base * weekendBoost * (0.75 + rand() * 0.5)));
  const avgViewSeconds = 24 + rand() * 9; // on a ~56s piece
  const retentionPct = Math.min(88, Math.round((avgViewSeconds / 56) * 100 + rand() * 18));
  const watchSeconds = Math.round(views * avgViewSeconds);
  const likes = Math.round(views * (0.038 + rand() * 0.02));
  const comments = Math.round(views * (0.0028 + rand() * 0.002));
  const shares = Math.round(views * (0.0075 + rand() * 0.006));
  const followsDelta = Math.round(views * (0.0016 + rand() * 0.0018));
  return {
    date: dateIst,
    views,
    watchSeconds,
    avgViewSeconds: Math.round(avgViewSeconds * 10) / 10,
    retentionPct,
    likes,
    comments,
    shares,
    followsDelta,
  };
}

export interface ChannelTotals {
  views: number;
  likes: number;
  comments: number;
  shares: number;
  follows: number;
  watchHours: number;
}

export function insights(episodeTitles: string[], totals: { instagram: ChannelTotals; youtube: ChannelTotals }) {
  const out: string[] = [];
  if (totals.instagram.views + totals.youtube.views === 0) return out;
  const leader = totals.instagram.views >= totals.youtube.views ? "Instagram Reels" : "YouTube Shorts";
  out.push(
    `${leader} currently leads reach — keep metadata platform-native rather than duplicating copy.`,
  );
  const er =
    (totals.instagram.likes + totals.instagram.comments + totals.instagram.shares) /
    Math.max(1, totals.instagram.views);
  if (er > 0.045)
    out.push(
      "Engagement rate above 4.5% — morning goshala scenes are resonating; schedule the Ganga series on weekend slots.",
    );
  out.push(
    "Completion rate holds longest on scenes with hands-in-frame activity; favour action POV over static beauty shots.",
  );
  out.push(
    "Simulated signal only — connect Buffer analytics (or platform APIs) before letting performance steer editorial.",
  );
  if (episodeTitles.length)
    out.push(`Next up from the planner queue: ${episodeTitles[0]}.`);
  return out;
}
